import 'package:crypto_simple/crypto_simple.dart';

void main(){
  CryptoSimpleSingleton(
    superKey: 2023,
    subKey: 47,
    secretKey: "MySecretKey! ;)",
    encryptionMode: EncryptionMode.Randomized,
  );
  String token = 'bearer 5@1#fG!';
  String enc = CryptoSimpleSingleton.instance.encryption(inputString: token);
  String dec = CryptoSimpleSingleton.instance.decryption(encryptedString: enc);
}
